#### Fix 14: Add Execution Timeout to `runClaudeSync`

**File:** `/Users/yashbaldha/Desktop/Boldteq App/claude-hub/src/server.js`
**Location:** Lines 803-819 (`runClaudeSync` function)

**Change:** Add a timeout parameter (default 120 seconds = 2 minutes) and kill the child process if it exceeds the limit:

```js
function runClaudeSync(prompt, timeoutMs = 120000) {
  return new Promise((resolve, reject) => {
    const claudePath = process.env.CLAUDE_PATH || 'claude';
    const childEnv = { ...process.env, HOME: os.homedir() };
    delete childEnv.CLAUDECODE;
    const proc = spawn(claudePath, ['-p'], { env: childEnv });
    let out = '', err = '';
    let killed = false;

    const timer = setTimeout(() => {
      killed = true;
      proc.kill('SIGTERM');
      // Force kill after 5 seconds if SIGTERM doesn't work
      setTimeout(() => { try { proc.kill('SIGKILL'); } catch {} }, 5000);
    }, timeoutMs);

    proc.stdout.on('data', d => { out += d.toString(); });
    proc.stderr.on('data', d => { err += d.toString(); });
    proc.on('close', code => {
      clearTimeout(timer);
      if (killed) reject(new Error(`Node execution timed out after ${timeoutMs / 1000}s`));
      else if (code !== 0) reject(new Error(err.trim() || `claude exited ${code}`));
      else resolve(out.trim());
    });
    proc.on('error', (e) => { clearTimeout(timer); reject(e); });
    proc.stdin.write(prompt, 'utf8');
    proc.stdin.end();
  });
}
```

**Why:** Without a timeout, a hung Claude process blocks the entire orchestration pipeline forever. The SSE connection stays open, and the user has no recourse except killing the server. 120s is generous for a single node; most should complete in under 60s.

